import React, { useCallback, useEffect } from 'react';
import { useNavigate } from 'react-router-dom'; // 'useHistory' 대신 'useNavigate'
import Header from './header';
import "../login.css"

const Login = ({ auth }) => {
    const navigate = useNavigate(); // useNavigate 사용

    const onLogin = (e) => {
        auth
            .login(e.target.textContent)
            .then(data => goToContact(data.user.uid));
    };

    const goToContact = useCallback((userId) => {
        navigate('/contact', { state: { id: userId } }); // useNavigate 적용
    }, [navigate]);

    useEffect(() => {
        auth.onAuthChange(user => { 
            if (user) {
                console.log("User ID:", user.uid);
                goToContact(user.uid);
            }
        });
    }, [auth, goToContact]);

    return (
        <section>
            <Header />
            <div className='home'>
                <h1>로그인</h1>
                <div className='center'>
                    <p>Your Email</p>
                    <input
                        type='email'
                        placeholder='이메일 입력'
                    />
                    <p>Password</p>
                    <input
                        type='password'
                        placeholder='비밀번호 입력'
                    />
                </div>
                <div style={{textAlign:'right'}}>
                    <a href=''>Forgot Password?</a>
                </div>
                <div className='login-buttons'>
                    <button>Login</button>
                </div>
                <div className="login-buttons2">
                    <button onClick={onLogin}>Login with Google</button>
                    <button onClick={onLogin}>Sign up with Google</button>
                </div>
                <div>
                    <p style={{textAlign: 'center'}}>Don't have an acount? <a href=''>Sign up</a></p>
                </div>
            </div>
        </section>
    );
};

export default Login;
